// The Owner-approved public legal texts (Điều khoản sử dụng, Chính sách quyền riêng tư) are authored ONCE in the backend pages
// (apps/backend/src/legal/terms-page.ts and privacy-page.ts). This module reads them and generates the browser copy that the
// phone web registration shows (apps/client-shared/src/legal-official.ts), so the web screen never carries a hand-typed copy.
//
//   node scripts/legal/official-legal.mjs --write   regenerate apps/client-shared/src/legal-official.ts
//   node scripts/legal/official-legal.mjs --check   exit 1 when the generated file is out of date
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const DEFAULT_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
export const GENERATED_PATH = 'apps/client-shared/src/legal-official.ts';

const decodeEntities = (text) =>
  text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');

// Terms: the `sections` literal of terms-page.ts is JSON-compatible.
function parseTerms(source) {
  const match = /const sections: readonly TermsSection\[\] = (\[[\s\S]*?\n\]);/.exec(source);
  if (!match) throw new Error('terms-page.ts: sections literal not found');
  const version = /TERMS_PAGE_VERSION = '([^']+)'/.exec(source)?.[1];
  if (!version) throw new Error('terms-page.ts: TERMS_PAGE_VERSION not found');
  return { version, sections: JSON.parse(match[1]).map(({ title, paragraphs }) => ({ title, paragraphs })) };
}

// Privacy: each section is `<section id="..."><h2>TITLE</h2><p>...</p>...</section>` inside the HTML literal.
function parsePrivacy(source) {
  const version = /PRIVACY_PAGE_VERSION = '([^']+)'/.exec(source)?.[1];
  if (!version) throw new Error('privacy-page.ts: PRIVACY_PAGE_VERSION not found');
  const sections = [];
  const sectionRe = /<section id="[^"]*"><h2>([^<]*)<\/h2>([\s\S]*?)<\/section>/g;
  let match;
  while ((match = sectionRe.exec(source)) !== null) {
    const paragraphs = [];
    const paragraphRe = /<p>([^<]*)<\/p>/g;
    let paragraph;
    while ((paragraph = paragraphRe.exec(match[2])) !== null) paragraphs.push(decodeEntities(paragraph[1]));
    if (paragraphs.length !== (match[2].match(/<p[\s>]/g) ?? []).length) throw new Error(`privacy-page.ts: a paragraph of "${match[1]}" does not parse`);
    sections.push({ title: decodeEntities(match[1]), paragraphs });
  }
  if (sections.length !== (source.match(/<section id=/g) ?? []).length) throw new Error('privacy-page.ts: a section does not parse');
  return { version, sections };
}

export function readOfficialLegal(root = DEFAULT_ROOT) {
  return {
    terms: parseTerms(readFileSync(join(root, 'apps/backend/src/legal/terms-page.ts'), 'utf8')),
    privacy: parsePrivacy(readFileSync(join(root, 'apps/backend/src/legal/privacy-page.ts'), 'utf8')),
  };
}

export function generateWebLegalSource(root = DEFAULT_ROOT) {
  const { terms, privacy } = readOfficialLegal(root);
  return [
    '// GENERATED by scripts/legal/official-legal.mjs from apps/backend/src/legal/{terms-page,privacy-page}.ts. Do not edit by hand.',
    '// Regenerate with: node scripts/legal/official-legal.mjs --write',
    '',
    'export interface OfficialLegalSection {',
    '  readonly title: string;',
    '  readonly paragraphs: readonly string[];',
    '}',
    '',
    `export const OFFICIAL_TERMS_VERSION = ${JSON.stringify(terms.version)};`,
    `export const OFFICIAL_PRIVACY_VERSION = ${JSON.stringify(privacy.version)};`,
    `export const OFFICIAL_TERMS_SECTIONS: readonly OfficialLegalSection[] = ${JSON.stringify(terms.sections, null, 2)};`,
    `export const OFFICIAL_PRIVACY_SECTIONS: readonly OfficialLegalSection[] = ${JSON.stringify(privacy.sections, null, 2)};`,
    '',
  ].join('\n');
}

const isMain = process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const generated = generateWebLegalSource();
  const target = join(DEFAULT_ROOT, GENERATED_PATH);
  if (process.argv.includes('--write')) {
    writeFileSync(target, generated, 'utf8');
    console.log(`wrote ${GENERATED_PATH}`);
  } else if (process.argv.includes('--check')) {
    const current = readFileSync(target, 'utf8');
    if (current !== generated) {
      console.error(`${GENERATED_PATH} is out of date; run: node scripts/legal/official-legal.mjs --write`);
      process.exit(1);
    }
    console.log(`${GENERATED_PATH} is up to date`);
  } else {
    process.stdout.write(generated);
  }
}
